ROWS = [
dict(id="T038", d="SM", t="Néel order in the spin-1/2 Heisenberg antiferromagnet on the square lattice",
 s="The ground state of the spin-1/2 quantum Heisenberg antiferromagnet H = Σ_{x~y} S_x·S_y on Z^2 (as a limit of finite boxes) has Néel long-range order: the staggered correlation (−1)^{|x|}⟨S_0·S_x⟩ stays bounded away from zero as |x| → ∞.",
 src="F. J. Dyson, E. H. Lieb and B. Simon, Phase transitions in quantum spin systems with isotropic and nonisotropic interactions, J. Stat. Phys. 18 (1978); T. Kennedy, E. H. Lieb and B. S. Shastry, Existence of Néel order in some spin-1/2 Heisenberg antiferromagnets, J. Stat. Phys. 53 (1988)",
 why="The parent model of the cuprate superconductors; reflection positivity proves order for larger spins and higher dimensions and stops exactly at spin 1/2 in the plane. The ferromagnetic counterpart is T012.",
 st="Order at low temperature in d ≥ 3 for S ≥ 1 (Dyson–Lieb–Simon 1978); ground-state order on Z^2 for S ≥ 1 (Neves–Perez, Phys. Lett. A 114 (1986); Kubo–Kishi, Phys. Rev. Lett. 61 (1988)) and for S = 1/2 in d ≥ 3 (Kennedy–Lieb–Shastry, J. Stat. Phys. 53 (1988)). Quantum Monte Carlo gives a staggered magnetisation near 0.31 for S = 1/2 on Z^2. Open for S = 1/2 on Z^2."),
dict(id="T039", d="COMB", t="Plurality is stablest and the standard simplex conjecture",
 s="For k ≥ 3 and ρ ∈ (0, 1), among partitions of Gaussian space R^n (n ≥ k − 1) into k sets of Gaussian measure 1/k each, the probability that ρ-correlated standard Gaussians X, Y land in the same set is maximised by the standard simplex partition (the Voronoi cells of a regular simplex centred at 0). The discrete form: among low-influence functions [k]^n → [k] with balanced outputs, plurality is the most noise-stable.",
 c="k = 2 is Borell's theorem (and Majority is Stablest, Mossel–O'Donnell–Oleszkiewicz 2010). The conjecture fails for every choice of unequal measures (Heilman–Mossel–Neeman, Israel J. Math. 213 (2016), arXiv:1403.0885).",
 src="S. Khot, G. Kindler, E. Mossel and R. O'Donnell, Optimal inapproximability results for MAX-CUT and other 2-variable CSPs?, SIAM J. Comput. 37 (2007); M. Isaksson and E. Mossel, New maximally stable Gaussian partitions with discrete applications, Israel J. Math. 189 (2012)",
 why="It would give the optimal hardness of approximation for MAX-k-CUT under the Unique Games Conjecture, and it is the multi-set extension of Borell's isoperimetric theorem.",
 st="The ρ → 1 limit, the Gaussian multi-bubble conjecture, was proved by Milman and Neeman (Ann. of Math. 2022, and later papers for more sets). Heilman (arXiv:2608.00333) proves k = 3 for ρ ∈ [−1/2, 2/5], which settles the MAX-3-CUT conjecture of Khot–Kindler–Mossel–O'Donnell under the Unique Games Conjecture; earlier k = 3 results for small ρ > 0 (Heilman, Electron. J. Probab. 19 (2014), arXiv:1211.7138; Heilman–Tarter, Forum Math. Sigma 9 (2021)). Open for k = 3 with ρ > 2/5 and for every k ≥ 4."),
dict(id="T040", x="SOLVED: two independent proofs, Vu Khac Ky and Tuan Tran, Dictators are most informative, arXiv:2609.24184, and Z. Chen, A. Gohari, A. Javanmard, H. Lin, V. Mirrokni, C. Nair and D. P. Woodruff, A proof of the most informative Boolean function conjecture, arXiv:2609.24931 (computer-assisted, with the argument verified in Lean), both 21 Sep 2026 and unrefereed. Read from the arXiv abstracts 14 Oct; flagged first by the w672 audit and checked by an agent.",d="COMB", t="The Courtade–Kumar conjecture (most informative Boolean function)",
 s="Let X be uniform on {−1,1}^n and Y the output of X through a binary symmetric channel with crossover probability α, applied coordinatewise. Then every Boolean f: {−1,1}^n → {−1,1} satisfies I(f(X); Y) ≤ 1 − h(α), with equality for dictator functions (h the binary entropy).",
 src="T. A. Courtade and G. R. Kumar, Which Boolean functions maximize mutual information on noisy inputs?, IEEE Trans. Inform. Theory 60 (2014)",
 why="A one-line information-theoretic statement about the hypercube that resists hypercontractivity and every Fourier argument tried so far.",
 st="True for α close to 1/2 (Samorodnitsky, IEEE Trans. Inform. Theory 62 (2016)); the two-function version I(f(X); g(Y)) ≤ 1 − h(α) was proved by Pichler–Piantanida–Matz (Ann. Appl. Probab. 28 (2018)). Open for general α."),
dict(id="T041", x="REPORTED SOLVED: J. Lu, S. Guo and E. X. Fang, Weak-type bounds for convolution on the Boolean hypercube, arXiv:2608.15515 (Aug 2026, unrefereed), prove ψ_{μ_a}(u) ≤ C_a/√(log u) for the biased product measures μ_a, which is Talagrand's 1989 conjecture. The abstract credits the discovery of the proof to an automated research agent ('Odin'), so it wants a careful human check; an independent martingale proof is in Shaposhnikov, arXiv:2609.11290. Read from the arXiv abstracts 14 Oct and 14 Nov; flagged first by the w672 audit and checked by an agent.",d="COMB", t="Talagrand's convolution conjecture on the hypercube",
 s="For f ≥ 0 on {−1,1}^n with E f = 1 and a fixed noise parameter t > 0, the noised function P_t f satisfies P(P_t f > s) ≤ C_t / (s √(log s)) for all s > e, with C_t independent of n: noise improves Markov's inequality by a factor √(log s).",
 src="M. Talagrand, A conjecture on convolution operators, and a non-Dunford–Pettis operator on L^1, Israel J. Math. 68 (1989)",
 why="Talagrand offered a prize for it; it asks for a form of regularisation by the heat flow that survives with no moment beyond L^1.",
 st="The Gaussian analogue (Ornstein–Uhlenbeck semigroup) is proved: Ball–Barthe–Bednorz–Oleszkiewicz–Wolff (Mathematika 59 (2013)) and Eldan–Lee (Duke Math. J. 167 (2018)) up to a log log factor, Lehec (Ann. Fac. Sci. Toulouse Math. 25 (2016)) removing it. On the cube, Chen proved the bound up to a factor (log log s)^{3/2} (arXiv:2511.19374, 2025). Lu–Guo–Fang (arXiv:2608.15515) remove the factor; Shaposhnikov (arXiv:2609.11290) gives self-contained martingale proofs of the Gaussian and Boolean cases with explicit dimension-free constants, and Marsh (arXiv:2611.14869) extends the result to tensor powers of finite-state Markov semigroups."),
dict(id="T042", d="COMB", t="The Aaronson–Ambainis conjecture",
 s="Every polynomial f: {−1,1}^n → [0,1] of degree at most d has a variable whose influence is at least (Var f / d)^{O(1)}.",
 src="S. Aaronson and A. Ambainis, The need for structure in quantum speedups, Theory of Computing 10 (2014)",
 url="https://arxiv.org/abs/0911.0996",
 why="It would show that quantum query algorithms give at most a polynomial speedup on almost all inputs for every total-domain problem without structure; it is a bounded-function strengthening of the Friedgut–Kalai–Naor and Bourgain theorems.",
 st="Proved for symmetric polynomials and several structured classes, and reduced to block-multilinear (decoupled) forms (O'Donnell–Zhao, arXiv:1512.01603); known with influence exponentially small in d. It holds after a positive fraction of random restrictions under a variance hypothesis (Bhattacharya, arXiv:2402.13952) and for completely bounded block-multilinear forms (Escudero Gutiérrez–Saucedo–Palazuelos, arXiv:2609.05201). Open for bounded polynomials in general."),
dict(id="T043", d="SM", t="Logarithmic corrections for self-avoiding walk in four dimensions",
 s="For the strictly self-avoiding walk on Z^4, c_n ~ A μ^n (log n)^{1/4} and the mean-square end-to-end distance is ~ D n (log n)^{1/4}.",
 src="Renormalisation-group prediction (Brézin, Le Guillou and Zinn-Justin, Phys. Rev. D 8 (1973); Duplantier, Nucl. Phys. B 275 (1986) 319–355); R. Bauerschmidt, D. C. Brydges and G. Slade, Introduction to a Renormalisation Group Method, Lecture Notes in Math. 2242, Springer (2019)",
 why="Four is the upper critical dimension: above it the lace expansion gives Brownian behaviour, below it nothing is proved; the logarithm at d = 4 is the test case for a rigorous renormalisation group.",
 st="Proved for the continuous-time weakly self-avoiding walk (Bauerschmidt–Brydges–Slade 2015; Bauerschmidt–Slade–Tomberg–Wallace 2017) and for hierarchical models (Brydges–Imbrie 2003). Open for the strictly self-avoiding walk. See also T015."),
dict(id="T044", d="SM", t="The crystallization problem",
 s="Classical particles in R^2 or R^3 interacting through the Lennard-Jones pair potential V(r) = r^{−12} − 2r^{−6} crystallize: ground states are periodic (triangular in the plane, close-packed in space), and at low positive temperature the infinite-volume Gibbs states have long-range order, positional in d = 3 and orientational in d = 2.",
 c="Three conjectures share this row: ground-state crystallization, order at low positive temperature, and the freezing of hard spheres at high density. Positional order is impossible in d = 2 at positive temperature (a Mermin–Wagner theorem, Richthammer 2007), which is why the planar statement is orientational.",
 src="C. Radin, Low temperature and the origin of crystalline symmetry, Int. J. Mod. Phys. B 1 (1987); X. Blanc and M. Lewin, The crystallization conjecture: a review, EMS Surv. Math. Sci. 2 (2015)",
 url="https://arxiv.org/abs/1504.01153",
 why="Why matter forms crystals is among the oldest unproved facts of statistical mechanics; even the zero-temperature problem is open for realistic potentials.",
 st="Zero temperature: proved in d = 2 for some short-range potentials (Radin 1981; Theil 2006) and in d = 3 for special potentials (Flatley–Theil, arXiv:1407.0692); open for the Lennard-Jones potential. Positive temperature: orientational order shown for some planar models with defects (Aumann, J. Stat. Phys. 160 (2015), arXiv:1408.5375); open for continuum particles."),
dict(id="T045", d="IPS", t="Fixation of zero-temperature Glauber dynamics for the Ising model",
 s="Run zero-temperature Glauber dynamics of the Ising model on Z^d from iid spins that are + with probability p. (a) For every d ≥ 2 and every p > 1/2, every site is eventually + forever. (b) For p = 1/2 and d ≥ 3, every site flips infinitely often.",
 src="L. R. Fontes, R. H. Schonmann and V. Sidoravicius, Stretched exponential fixation in stochastic Ising models at zero temperature, Comm. Math. Phys. 228 (2002); S. Nanda, C. M. Newman and D. L. Stein, Dynamics of Ising spin systems at zero temperature, in On Dobrushin's Way (AMS, 2000)",
 why="The basic question of coarsening after a quench: whether the majority phase wins from any bias, and whether a symmetric quench ever freezes.",
 st="For p = 1/2 and d = 2 every site flips infinitely often (Nanda–Newman–Stein 2000). Fixation at + for p close to 1 (Fontes–Schonmann–Sidoravicius 2002) and for p > 1/2 + ε_d with ε_d → 0 as d → ∞ (Morris 2011). Open for p slightly above 1/2 in fixed d, and (b) is open."),
dict(id="T046", d="IPS", t="Lifshitz law for the low-temperature Ising Glauber dynamics",
 s="For continuous-time Glauber dynamics (each site updated at rate one) of the two-dimensional Ising model at any temperature below T_c, in an L × L box with + boundary conditions, the mixing time is of order L^2 (up to constants depending on the temperature).",
 src="I. M. Lifshitz, Kinetics of ordering during second-order phase transitions, Sov. Phys. JETP 15 (1962); D. S. Fisher and D. A. Huse, Dynamics of droplet fluctuations in pure and random Ising systems, Phys. Rev. B 36 (1987); F. Martinelli, Lectures on Glauber dynamics for discrete spin models, Saint-Flour 1997 (Lecture Notes in Math. 1717, 1999)",
 why="Motion by mean curvature of the interface is the predicted mechanism; proving it at positive temperature needs control of the interface over long times.",
 st="At zero temperature: order L^2 in d = 2 (Lacoin–Simenhaus–Toninelli, arXiv:1112.3160) and up to logarithms in all d (Lacoin, arXiv:1102.3466). Below T_c in d = 2: quasi-polynomial bound L^{O(log L)} (Lubetzky–Martinelli–Sly–Toninelli 2013). Gheissari–Sly (arXiv:2605.08052) prove rapid phase ordering from sufficiently biased iid initial states for every β > β_c in two dimensions; their proof still uses the quasi-polynomial plus-boundary bound. A polynomial bound at positive temperature is open."),
dict(id="T047", d="RW", t="Recurrence and transience of once-reinforced random walk",
 s="Once-reinforced random walk on Z^d (an edge already crossed has weight 1 + δ, an uncrossed edge weight 1) is recurrent on Z^2 for every δ > 0; on Z^d with d ≥ 3 it is transient for small δ and recurrent for large δ.",
 c="The precise conjectured picture in d ≥ 3 is to verify.",
 src="B. Davis, Reinforced random walk, Probab. Theory Related Fields 84 (1990); R. Pemantle, A survey of random processes with reinforcement, Probab. Surv. 4 (2007)",
 url="https://arxiv.org/abs/math/0610076",
 why="The simplest self-interacting walk whose long-time behaviour is unknown on the plane; the methods that settled the linearly reinforced walk (through the VRJP) do not apply.",
 st="Recurrent on Z (Davis, Probab. Theory Related Fields 84 (1990)) and on ladders (Sellke, Electron. J. Probab. 11 (2006)); a recurrence/transience phase transition on trees and on Z^d-like trees (Kious–Sidoravicius 2018; Collevecchio–Kious–Sidoravicius 2020). Transient and diffusive for d ≥ 6 and small reinforcement (Elboim–Kozma, arXiv:2601.17972, Jan 2026); the expected range is at least of order n^{d/(d+1)} for every d ≥ 2 and every reinforcement (Bou-Rabee–Peres, arXiv:2610.00090, Sep 2026), the order predicted for large reinforcement. Open on Z^2, for d = 3, 4, 5, and for large reinforcement in every d ≥ 3."),
dict(id="T048", d="TREE", t="Monotonicity of the speed of biased random walk on Galton–Watson trees",
 s="For λ-biased random walk on a supercritical Galton–Watson tree with no leaves and mean offspring m > 1 (bias λ toward the root, transient for λ < m), the speed is strictly decreasing in λ on (0, m).",
 src="R. Lyons, R. Pemantle and Y. Peres, Biased random walks on Galton–Watson trees, Probab. Theory Related Fields 106 (1996); R. Lyons and Y. Peres, Probability on Trees and Networks (Cambridge, 2016)",
 why="A natural monotonicity that fails on trees with leaves (traps make the speed zero for strong bias) and should hold without them, yet resists every coupling.",
 st="Proved for λ ≤ 1/2 (Aïdékon, arXiv:1111.4313) and for λ near 0 (Ben Arous–Fribergh–Sidoravicius, arXiv:1111.5865); the derivative at λ = 1 is known through the Einstein relation (Ben Arous–Hu–Olla–Zeitouni, arXiv:1106.4387). with computer assistance, strictly decreasing on [0, 1.755] for offspring uniform on {2, 3} (Mandarapu–Kunkunuru, arXiv:2609.29894, Sep 2026). Open on the rest of (0, m)."),
dict(id="T049", d="PERC", t="Number of components of the minimal spanning forest on Z^d",
 s="The minimal spanning forest of Z^d with iid uniform edge weights (free and wired coincide on Z^d) is a single tree for d < 8 and has infinitely many components for d > 8.",
 src="C. M. Newman and D. L. Stein, Spin-glass model with dimension-dependent ground state multiplicity, Phys. Rev. Lett. 72 (1994); R. Lyons, Y. Peres and O. Schramm, Minimal spanning forests, Ann. Probab. 34 (2006)",
 why="It is the zero-temperature limit of a disordered system and is tied to invasion percolation and the critical percolation two-point function; the predicted switch at d = 8 comes from the critical exponents.",
 st="A single tree on Z^2 (Alexander 1995). On amenable transitive graphs the free and wired forests agree (Lyons–Peres–Schramm, arXiv:math/0412263). Open for every d ≥ 3."),
dict(id="T050", d="PERC", t="Strict convexity of the limit shape in first-passage percolation",
 s="For first-passage percolation on Z^d, d ≥ 2, with iid continuous edge weights satisfying E min(t_1, …, t_{2d})^d < ∞ (so that the shape theorem holds), the limit shape (the asymptotic shape of the ball of passage time t, scaled by t) is strictly convex.",
 c="Weights with an atom at their minimum of mass above the directed-percolation threshold give flat edges (Durrett–Liggett 1981), hence the continuity assumption.",
 src="H. Kesten, Aspects of first passage percolation, École d'Été de Saint-Flour XIV (Lecture Notes in Math. 1180, 1986); A. Auffinger, M. Damron and J. Hanson, 50 Years of First-Passage Percolation (AMS University Lecture Series 68, 2017)",
 url="https://arxiv.org/abs/1511.03262",
 why="Almost every deeper result on geodesics and fluctuations in first-passage percolation assumes strict convexity or curvature of the limit shape, which is unproved for any continuous distribution.",
 st="The limit shape is compact and convex (Cox–Durrett 1981); examples of non-polygonal shapes (Damron–Hochman 2013). Strict convexity is unknown for every continuous distribution, including exponential weights. Update, 14 Nov 2026: the OpenAI math release (github.com/openai/math; AI-written, unrefereed) has 'Strict convexity and differentiability of the planar exponential first-passage limit shape' (24 Sep 2026), which claims strict convexity for iid exponential weights on Z^2 (its Lean files omit this part); other laws and d >= 3 remain open."),
]
